window.VO = [{"id":"n01b","text":"You're the witness. Remember the man who took your rings.","at":0.24,"t0":0.12,"t1":3.055},{"id":"n02","text":"Grey hair. A moustache.","at":6.81,"t0":3.405,"t1":4.97},{"id":"n03","text":"Now the police show you six men.","at":12.34,"t0":6.17,"t1":7.92},{"id":"n04","text":"Which one is him?","at":16.54,"t0":8.27,"t1":9.37},{"id":"n05b","text":"Number four? That's who the women picked, in Victorian London.","at":23.14,"t0":11.57,"t1":14.745},{"id":"n06","text":"His name was Adolf Beck. He wasn't the swindler.","at":30.69,"t0":15.345,"t1":18.275},{"id":"n07","text":"He was the only man in that line with grey hair and a moustache.","at":37.95,"t0":18.975,"t1":22.715},{"id":"n08","text":"The women remembered grey hair and a moustache. The line gave them only one man to match.","at":46.13,"t0":23.065,"t1":28.22},{"id":"n09","text":"Beck went to prison twice, until the real swindler was caught in nineteen oh four.","at":57.84,"t0":28.92,"t1":33.495},{"id":"n10","text":"His case helped create England's Court of Criminal Appeal.","at":67.99,"t0":33.995,"t1":36.915},{"id":"n11","text":"Today, every face in a fair lineup should fit the description.","at":74.83,"t0":37.415,"t1":40.69}];
